f='/home/claude/president/index.html';s=open(f).read()
def rep(a,b,n=1):
    global s
    assert s.count(a)==n,(a[:70],s.count(a));s=s.replace(a,b)
# radar avec profil type du rôle
rep("function radar(at){\n  const W=300,cx=150,cy=135,R0=95,n=at.length;","function radar(at,ideal,lab){\n  const W=300,cx=150,cy=135,R0=95,n=at.length;")
rep("""  g+=`<polygon points="${at.map((a,k)=>pt(k,R0*a.v/100).map(v=>v.toFixed(1)).join(',')).join(' ')}" style="fill:var(--flood);fill-opacity:.25;stroke:var(--flood)" stroke-width="2"/>`;
  return `<svg viewBox="0 0 ${W} 270" class="radar" role="img" aria-label="Profil du joueur">${g}</svg>`;""","""  if(ideal)g+=`<polygon points="${ideal.map((v,k)=>pt(k,R0*clamp(v,0,100)/100).map(x=>x.toFixed(1)).join(',')).join(' ')}" fill="none" stroke="#9fd3ff" stroke-width="1.4" stroke-dasharray="4 3" opacity=".85"/>`;
  g+=`<polygon points="${at.map((a,k)=>pt(k,R0*a.v/100).map(v=>v.toFixed(1)).join(',')).join(' ')}" style="fill:var(--flood);fill-opacity:.25;stroke:var(--flood)" stroke-width="2"/>`;
  at.forEach((a,k)=>{const [x,y]=pt(k,R0*a.v/100);g+=`<circle cx="${x.toFixed(1)}" cy="${y.toFixed(1)}" r="2.6" style="fill:var(--flood)"/>`;});
  if(lab)g+=`<text x="${W/2}" y="266" text-anchor="middle" style="fill:#9fd3ff;font-size:10.5px">- - - profil type : ${lab}</text>`;
  return `<svg viewBox="0 0 ${W} 270" class="radar" role="img" aria-label="Profil du joueur">${g}</svg>`;""")
rep("""    <div class="grid g2" style="align-items:center">${radar(at)}<div style="display:grid;gap:6px">${at.map(a=>`<div class="attr"><span>${a.n}</span><div class="bar"><i style="width:${a.v}%"></i></div><b class="num">${a.v}</b></div>`).join('')}</div></div>""",
"""    <div class="radwrap">${(()=>{ensureRole(p);const off=ROFF[p.role]||[];const ideal=at.map((a,k)=>p.ovr+(off[k]||0));return radar(at,ideal,ROLE[p.role]?ROLE[p.role].n.toLowerCase():'');})()}<div style="display:grid;gap:6px">${at.map(a=>{const d=a.v-p.ovr;return `<div class="attr ${d>=6?'hi':d<=-6?'lo':''}"><span>${a.n}</span><div class="bar"><i style="width:${a.v}%"></i></div><b class="num">${a.v}</b></div>`;}).join('')}<div class="muted" style="font-size:11.5px">En vert : ses points forts · en rouge : ses points faibles (par rapport à sa note).</div></div></div>""")
rep("""    const notes=p.notes.length?`<svg viewBox="0 0 200 52" class="chart" style="max-width:280px">${p.notes.map((n,i)=>`<rect x="${i*20+3}" y="${52-n*5}" width="14" height="${n*5}" rx="2" style="fill:${n>=7?'var(--good)':n<5?'var(--bad)':'var(--flood)'}"/>`).join('')}</svg>`:'<span class="muted">Pas encore noté cette saison.</span>';""",
"""    const notes=p.notes.length?(()=>{const av=p.notes.reduce((a,b)=>a+b,0)/p.notes.length,H=70,y=n=>H-6-(n-2)*(H-18)/8;return `<svg viewBox="0 0 ${p.notes.length*26+40} ${H}" class="chart" style="max-width:${p.notes.length*26+40}px">${p.notes.map((n,i)=>`<rect x="${i*26+6}" y="${y(n)}" width="18" height="${H-6-y(n)}" rx="3" style="fill:${n>=7?'var(--good)':n<5?'var(--bad)':'var(--flood)'}"/><text x="${i*26+15}" y="${y(n)-3}" text-anchor="middle" style="font:700 9px var(--mono);fill:var(--chalk,#e9efe5)">${String(n).replace('.',',')}</text>`).join('')}<line x1="2" x2="${p.notes.length*26+4}" y1="${y(av)}" y2="${y(av)}" stroke="#9fd3ff" stroke-dasharray="3 3"/><text x="${p.notes.length*26+8}" y="${y(av)+3}" style="font:700 9px var(--mono);fill:#9fd3ff">moy. ${av.toFixed(1).replace('.',',')}</text></svg>`;})():'<span class="muted">Pas encore noté cette saison.</span>';""")
rep(".sp-off{display:flex;",".radwrap{display:grid;grid-template-columns:minmax(230px,300px) 1fr;gap:14px;align-items:center}@media (max-width:640px){.radwrap{grid-template-columns:1fr}.radwrap .radar{max-width:300px;margin:0 auto}}\n.attr.hi .bar i{background:var(--good)}.attr.hi b{color:var(--good)}.attr.lo .bar i{background:var(--bad)}.attr.lo b{color:var(--bad)}\n.sp-off{display:flex;")
open(f,'w').write(s);print('ok')
